selector_to_html = {"a[href=\"#capabilities\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Capabilities<a class=\"headerlink\" href=\"#capabilities\" title=\"Link to this heading\">\u00b6</a></h1><p>This page shows what Pyskyfire can do at-a-glance. The goal of this page is to give you an overview of the current capabilities of the package, so that you can better understand if it fits your needs.</p><p>Every plot below is live output. Each one is generated by the example or\nvalidation case it belongs to and embedded here directly, so the page cannot\ndrift away from what the code currently produces. Drag, zoom, and toggle traces\nin the legend to explore them.</p>", "a[href=\"#analyze-pumps-and-turbomachinery\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Analyze pumps and turbomachinery<a class=\"headerlink\" href=\"#analyze-pumps-and-turbomachinery\" title=\"Link to this heading\">\u00b6</a></h2>", "a[href=\"../validation/rl10a-3-3a.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">RL10A-3-3A<a class=\"headerlink\" href=\"#rl10a-3-3a\" title=\"Link to this heading\">\u00b6</a></h1><p>The HTML documentation build replaces this page with the standalone\nRL10A-3-3A validation report. This source page exists so that Sphinx can include\nthe report in its navigation and so that non-HTML documentation builders have a\nuseful fallback.</p><p>The generated report is maintained at\n<code class=\"docutils literal notranslate\"><span class=\"pre\">validation/RL10/RL10A-3-3A_Report.html</span></code> in the repository.</p>", "a[href=\"#generate-plots-and-reports\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Generate plots and reports<a class=\"headerlink\" href=\"#generate-plots-and-reports\" title=\"Link to this heading\">\u00b6</a></h2><p>The <a class=\"reference internal\" href=\"../validation/rl10a-3-3a.html\"><span class=\"std std-doc\">RL10A-3-3A validation report</span></a> is one such\nreport: a single self-contained HTML file holding every figure on this page and\nmany more.</p>", "a[href=\"#model-film-cooling\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Model film cooling<a class=\"headerlink\" href=\"#model-film-cooling\" title=\"Link to this heading\">\u00b6</a></h2><p><em>The same ethanol/N\u2082O chamber run twice, from <code class=\"docutils literal notranslate\"><span class=\"pre\">examples/film_cooling/coupled_film_regen.py</span></code>:\nregeneratively cooled alone, and with a film ring injecting part-way down the\nbarrel. The dotted markers show the injection station and the liquid-film\ndryout point.</em></p>", "a[href=\"#support-scripted-design-studies\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Support scripted design studies<a class=\"headerlink\" href=\"#support-scripted-design-studies\" title=\"Link to this heading\">\u00b6</a></h2>", "a[href=\"#visualize-cooling-channel-geometry-in-3d\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Visualize cooling-channel geometry in 3D<a class=\"headerlink\" href=\"#visualize-cooling-channel-geometry-in-3d\" title=\"Link to this heading\">\u00b6</a></h2><p><em>The reconstructed RL10A-3-3A thrust chamber from the validation case. 180 long\ntubes run the full length of the chamber and throat; 180 short tubes join them\nat the nozzle interlacing manifold, so the two sets alternate around the\ncircumference downstream of it.</em></p>", "a[href=\"#estimate-hot-gas-and-nozzle-performance\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Estimate hot-gas and nozzle performance<a class=\"headerlink\" href=\"#estimate-hot-gas-and-nozzle-performance\" title=\"Link to this heading\">\u00b6</a></h2><p><em>Combustion-gas dynamic viscosity along the RL10 chamber and nozzle. Every\nproperty in the list above is available on the same axial grid.</em></p>", "a[href=\"#generate-thrust-chamber-and-nozzle-geometry\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Generate thrust chamber and nozzle geometry<a class=\"headerlink\" href=\"#generate-thrust-chamber-and-nozzle-geometry\" title=\"Link to this heading\">\u00b6</a></h2><p><em>Contour of the methane engine from the <a class=\"reference internal\" href=\"../tutorials/advanced-simulation.html\"><span class=\"std std-doc\">advanced simulation\ntutorial</span></a>, sized from thrust, chamber\npressure, expansion ratio, and <span class=\"math notranslate nohighlight\">\\(L^*\\)</span>.</em></p>", "a[href=\"../tutorials/advanced-simulation.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Engine-Cycle Simulation<a class=\"headerlink\" href=\"#engine-cycle-simulation\" title=\"Link to this heading\">\u00b6</a></h1><p>This tutorial goes over a complete engine cycle, using an example of a dual-expander methane/oxygen cycle. It assumes that you are already comfortable with the thrust-chamber, cooling-circuit, and regenerative heat-transfer objects introduced in <a class=\"reference internal\" href=\"../tutorials/minimal-simulation.html\"><span class=\"doc\">Minimal Simulation</span></a>.</p><p>The complete example includes the simulation, report generator, and an\nexternal Onshape export workflow:</p>", "a[href=\"#solve-full-engine-cycle-networks\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Solve full engine-cycle networks<a class=\"headerlink\" href=\"#solve-full-engine-cycle-networks\" title=\"Link to this heading\">\u00b6</a></h2><p><em>The converged RL10A-3-3A expander cycle. The schematic is editable: drag blocks\nto rearrange it, and save the layout back as JSON to keep the arrangement.</em></p><p>Once the cycle is closed, every station carries a full thermodynamic state.\nHere it is compared station by station against the published RL10 fuel-side\nengine data:</p>", "a[href=\"#solve-regenerative-cooling-problems\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Solve regenerative cooling problems<a class=\"headerlink\" href=\"#solve-regenerative-cooling-problems\" title=\"Link to this heading\">\u00b6</a></h2><p>The four plots below come from the <a class=\"reference internal\" href=\"../validation/rl10a-3-3a.html\"><span class=\"std std-doc\">RL10A-3-3A validation\ncase</span></a>, where the Pyskyfire solution is compared\nagainst digitized curves from the published NASA modeling report.</p>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 600, interactive: false,
                onShow(instance) {MathJax.typesetPromise([instance.popper]).then(() => {});},
            });
        };
    };
    console.log("tippy tips loaded!");
};
